"""Install the requested baby-profile lifecycle notices with private source backups.
Run --check first; schema migration and scheduler activation remain explicit steps.
"""
from pathlib import Path
from datetime import datetime
import json, os, re, shutil, subprocess, sys, tempfile
root=Path(sys.argv[1]).resolve(strict=True)
apply='--apply' in sys.argv[2:]
files=json.loads('{"database/migrations/2026_11_02_160000_add_system_event_tracking_to_notifications_drivers.php": "<?php\\n\\nuse Illuminate\\\\Database\\\\Migrations\\\\Migration;\\nuse Illuminate\\\\Database\\\\Schema\\\\Blueprint;\\nuse Illuminate\\\\Support\\\\Facades\\\\Schema;\\n\\nreturn new class extends Migration\\n{\\n    public function up(): void\\n    {\\n        Schema::table(\'notifications_drivers\', function (Blueprint $table) {\\n            $table->string(\'system_event_key\', 160)->nullable()->unique();\\n            $table->timestamp(\'mail_sent_at\')->nullable();\\n        });\\n    }\\n\\n    public function down(): void\\n    {\\n        Schema::table(\'notifications_drivers\', function (Blueprint $table) {\\n            $table->dropUnique([\'system_event_key\']);\\n            $table->dropColumn([\'system_event_key\', \'mail_sent_at\']);\\n        });\\n    }\\n};\\n", "app/Mail/BabyProfileLifecycleMail.php": "<?php\\n\\nnamespace App\\\\Mail;\\n\\nuse Illuminate\\\\Bus\\\\Queueable;\\nuse Illuminate\\\\Mail\\\\Mailable;\\nuse Illuminate\\\\Queue\\\\SerializesModels;\\n\\nclass BabyProfileLifecycleMail extends Mailable\\n{\\n    use Queueable, SerializesModels;\\n\\n    public function __construct(\\n        public readonly string $plate,\\n        public readonly string $expiresOn,\\n        public readonly string $phase,\\n        public readonly string $vehicleUrl,\\n    ) {}\\n\\n    public function build(): static\\n    {\\n        $expired = $this->phase === \'expired\';\\n        $title = $expired ? \'É hora de atualizar seu perfil.\' : \'Seu perfil precisa de atenção em breve.\';\\n        $description = $expired\\n            ? \'O prazo de dois anos do perfil Recém-nascido foi encerrado em \' . $this->expiresOn . \'.\'\\n            : \'O perfil Recém-nascido completa dois anos em \' . $this->expiresOn . \'. Este é um lembrete para você se preparar.\';\\n        $subject = $expired ? \'Atualize o perfil e a etiqueta do seu veículo — Identifica Trânsito\' : \'Seu perfil Recém-nascido expira em breve — Identifica Trânsito\';\\n        $html = \'<!doctype html><html lang=\\"pt-BR\\"><meta charset=\\"utf-8\\"><body style=\\"margin:0;padding:32px 16px;background:#f5f5fc;font-family:Arial,sans-serif;color:#1b2237\\"><main style=\\"max-width:560px;margin:auto;background:#fff;border:1px solid #e5e6f0;border-radius:20px;padding:32px\\"><p style=\\"color:#2420db;font-size:13px;font-weight:bold;letter-spacing:1px\\">IDENTIFICA TRÂNSITO</p><h1 style=\\"font-size:28px;line-height:1.2\\">\' . e($title) . \'</h1><p style=\\"line-height:1.7\\">Veículo: <strong>\' . e($this->plate) . \'</strong></p><p style=\\"line-height:1.7\\">\' . e($description) . \'</p><p style=\\"line-height:1.7\\">Atualize o perfil do veículo e entre em contato com a equipe para orientar a troca da etiqueta.</p><p style=\\"margin:28px 0\\"><a href=\\"\' . e($this->vehicleUrl) . \'\\" style=\\"display:inline-block;background:#2420db;color:#fff;text-decoration:none;border-radius:10px;padding:15px 20px\\">Acessar meu veículo</a></p><p style=\\"color:#6d7488;font-size:12px;line-height:1.6\\">Este aviso usa a data informada no cadastro. Se os dados estiverem incorretos, revise-os na sua conta. Uma etiqueta. Um sinal de cuidado.</p></main></body></html>\';\\n        return $this->subject($subject)->html($html);\\n    }\\n}\\n", "app/Jobs/NotifyBabyProfileLifecycleJob.php": "<?php\\n\\nnamespace App\\\\Jobs;\\n\\nuse App\\\\Enums\\\\VehicleUsageProfileEnum;\\nuse App\\\\Mail\\\\BabyProfileLifecycleMail;\\nuse App\\\\Models\\\\Vehicle;\\nuse Illuminate\\\\Bus\\\\Queueable;\\nuse Illuminate\\\\Contracts\\\\Queue\\\\ShouldBeUnique;\\nuse Illuminate\\\\Contracts\\\\Queue\\\\ShouldQueue;\\nuse Illuminate\\\\Foundation\\\\Bus\\\\Dispatchable;\\nuse Illuminate\\\\Queue\\\\InteractsWithQueue;\\nuse Illuminate\\\\Queue\\\\SerializesModels;\\nuse Illuminate\\\\Support\\\\Carbon;\\nuse Illuminate\\\\Support\\\\Facades\\\\DB;\\nuse Illuminate\\\\Support\\\\Facades\\\\Mail;\\n\\nclass NotifyBabyProfileLifecycleJob implements ShouldQueue, ShouldBeUnique\\n{\\n    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;\\n\\n    public int $tries = 3;\\n    public int $uniqueFor = 3600;\\n    public array $backoff = [60, 300, 900];\\n\\n    public function __construct(\\n        private readonly int $vehicleId,\\n        private readonly int $ownerId,\\n        private readonly string $expiresOn,\\n        private readonly string $phase,\\n    ) {}\\n\\n    public static function expiryDate(mixed $birthDate): ?Carbon\\n    {\\n        // A DATE is a calendar day, not a UTC timestamp to convert to local time.\\n        $date = $birthDate instanceof \\\\DateTimeInterface ? $birthDate->format(\'Y-m-d\') : substr((string) $birthDate, 0, 10);\\n        if (!preg_match(\'/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/\', $date) || !checkdate((int) substr($date, 5, 2), (int) substr($date, 8, 2), (int) substr($date, 0, 4))) {\\n            return null;\\n        }\\n        return Carbon::createFromFormat(\'!Y-m-d\', $date, \'America/Sao_Paulo\')->addYearsNoOverflow(2);\\n    }\\n\\n    public static function eventKey(int $vehicleId, int $ownerId, string $expiresOn, string $phase): string\\n    {\\n        return \\"baby-profile:{$vehicleId}:{$ownerId}:{$expiresOn}:{$phase}\\";\\n    }\\n\\n    public function uniqueId(): string\\n    {\\n        return self::eventKey($this->vehicleId, $this->ownerId, $this->expiresOn, $this->phase);\\n    }\\n\\n    public function handle(): void\\n    {\\n        if (!in_array($this->phase, [\'expiring\', \'expired\'], true)) {\\n            return;\\n        }\\n        $vehicle = Vehicle::query()->with(\'user\')->find($this->vehicleId);\\n        $profile = $vehicle?->usage_profile;\\n        $profile = $profile instanceof \\\\BackedEnum ? $profile->value : (int) $profile;\\n        if (!$vehicle || !$vehicle->user || (int) $vehicle->user_id !== $this->ownerId\\n            || $profile !== VehicleUsageProfileEnum::RecemNascido->value\\n            || !$vehicle->usage_profile_baby_date_of_birth) {\\n            return;\\n        }\\n        $expires = self::expiryDate($vehicle->usage_profile_baby_date_of_birth);\\n        if (!$expires) {\\n            return;\\n        }\\n        $today = Carbon::today(\'America/Sao_Paulo\');\\n        if ($expires->toDateString() !== $this->expiresOn\\n            || ($this->phase === \'expired\' && $expires->isAfter($today))\\n            || ($this->phase === \'expiring\' && ($expires->lessThanOrEqualTo($today) || $expires->isAfter($today->copy()->addMonthNoOverflow())))) {\\n            return;\\n        }\\n        $key = $this->uniqueId();\\n        DB::table(\'notifications_drivers\')->insertOrIgnore([\\n            \'user_id\' => $this->ownerId,\\n            \'driver_id\' => $this->ownerId,\\n            \'plate\' => $vehicle->plate,\\n            \'type\' => $this->phase === \'expired\' ? 6 : 5,\\n            \'read\' => 0,\\n            \'system_event_key\' => $key,\\n            \'created_at\' => now(),\\n            \'updated_at\' => now(),\\n        ]);\\n        $notice = DB::table(\'notifications_drivers\')->where(\'system_event_key\', $key)->first();\\n        if (!$notice || $notice->mail_sent_at) {\\n            return;\\n        }\\n        $url = rtrim((string) config(\'app.url_front\'), \'/\') . \'/dashboard/veiculos/detalhes/\' . $vehicle->id;\\n        Mail::to($vehicle->user->email)->send(new BabyProfileLifecycleMail((string) $vehicle->plate, $expires->format(\'d/m/Y\'), $this->phase, $url));\\n        DB::table(\'notifications_drivers\')->where(\'id\', $notice->id)->update([\'mail_sent_at\' => now(), \'updated_at\' => now()]);\\n    }\\n}\\n", "app/Console/Commands/NotifyBabyProfileExpiringCommand.php": "<?php\\n\\nnamespace App\\\\Console\\\\Commands;\\n\\nuse App\\\\Enums\\\\VehicleUsageProfileEnum;\\nuse App\\\\Jobs\\\\NotifyBabyProfileLifecycleJob;\\nuse App\\\\Models\\\\Vehicle;\\nuse Illuminate\\\\Console\\\\Command;\\nuse Illuminate\\\\Support\\\\Carbon;\\nuse Illuminate\\\\Support\\\\Facades\\\\DB;\\n\\nclass NotifyBabyProfileExpiringCommand extends Command\\n{\\n    protected $signature = \'vehicles:notify-baby-profile-expiring {--dry-run : Only count eligible notices} {--as-of= : Reference date, only with dry-run}\';\\n    protected $description = \'Avisa no painel e por e-mail antes e ao completar os dois anos do perfil recém-nascido.\';\\n\\n    public function handle(): int\\n    {\\n        if ($this->option(\'as-of\') && !$this->option(\'dry-run\')) {\\n            $this->error(\'--as-of is only allowed with --dry-run.\');\\n            return self::FAILURE;\\n        }\\n        $reference = $this->option(\'as-of\');\\n        if ($reference && (!preg_match(\'/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/\', $reference) || !checkdate((int) substr($reference, 5, 2), (int) substr($reference, 8, 2), (int) substr($reference, 0, 4)))) {\\n            $this->error(\'Invalid reference date.\');\\n            return self::FAILURE;\\n        }\\n        $today = $reference ? Carbon::parse($reference, \'America/Sao_Paulo\')->startOfDay() : Carbon::today(\'America/Sao_Paulo\');\\n        $warningEnd = $today->copy()->addMonthNoOverflow();\\n        $counts = [\'expiring\' => 0, \'expired\' => 0];\\n\\n        Vehicle::query()\\n            ->where(\'usage_profile\', VehicleUsageProfileEnum::RecemNascido->value)\\n            ->whereNotNull(\'usage_profile_baby_date_of_birth\')\\n            ->whereDate(\'usage_profile_baby_date_of_birth\', \'<=\', $today->copy()->subMonthsNoOverflow(22)->toDateString())\\n            ->chunkById(100, function ($vehicles) use ($today, $warningEnd, &$counts) {\\n                foreach ($vehicles as $vehicle) {\\n                    $expires = NotifyBabyProfileLifecycleJob::expiryDate($vehicle->usage_profile_baby_date_of_birth);\\n                    if (!$expires || $expires->isAfter($warningEnd)) {\\n                        continue;\\n                    }\\n                    $phase = $expires->lessThanOrEqualTo($today) ? \'expired\' : \'expiring\';\\n                    $key = NotifyBabyProfileLifecycleJob::eventKey((int) $vehicle->id, (int) $vehicle->user_id, $expires->toDateString(), $phase);\\n                    if (DB::table(\'notifications_drivers\')->where(\'system_event_key\', $key)->whereNotNull(\'mail_sent_at\')->exists()) {\\n                        continue;\\n                    }\\n                    $counts[$phase]++;\\n                    if (!$this->option(\'dry-run\')) {\\n                        NotifyBabyProfileLifecycleJob::dispatch((int) $vehicle->id, (int) $vehicle->user_id, $expires->toDateString(), $phase);\\n                    }\\n                }\\n            });\\n        $this->info(($this->option(\'dry-run\') ? \'DRY RUN — \' : \'Enfileiradas — \') . json_encode($counts));\\n        return self::SUCCESS;\\n    }\\n}\\n"}')
resource=root/'app/Http/Resources/NotificationDriverResource.php'
original=resource.read_bytes().decode()
pattern=r'NotificationDriverEnum::tryFrom\(\(int\)\s*\$this->type\)\?->label\(\)'
labels="match ((int) $this->type) { 5 => 'Seu perfil Recém-nascido expira em breve. Prepare-se para atualizar o perfil e a etiqueta.', 6 => 'O prazo de dois anos do perfil Recém-nascido terminou. Atualize o perfil e solicite a troca da etiqueta.', default => NotificationDriverEnum::tryFrom((int) $this->type)?->label() }"
updated,count=re.subn(pattern,lambda _:labels,original)
assert count==1,'Unexpected notification resource; no changes applied'
files[str(resource.relative_to(root))]=updated
routes=root/'routes/console.php'; source=routes.read_text()
old="Schedule::command('vehicles:notify-baby-profile-expiring')->daily();"
new="Schedule::command('vehicles:notify-baby-profile-expiring')->dailyAt('09:00')->timezone('America/Sao_Paulo')->withoutOverlapping();"
assert source.count(old)==1,'Unexpected scheduler configuration; no changes applied'
files['routes/console.php']=source.replace(old,new)
command=root/'app/Console/Commands/NotifyBabyProfileExpiringCommand.php'
assert 'vehicles:notify-baby-profile-expiring' in command.read_text()
new_paths=[p for p in files if p not in ['app/Console/Commands/NotifyBabyProfileExpiringCommand.php','app/Http/Resources/NotificationDriverResource.php','routes/console.php']]
assert all(not (root/p).exists() for p in new_paths),'New lifecycle files already present'
with tempfile.TemporaryDirectory(prefix='it-baby-preflight-') as td:
    staged=Path(td)
    for name,content in files.items():
        p=staged/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
        subprocess.run(['php','-l',str(p)],check=True)
    if not apply:
        print('CHECK PASSED; no application files changed.');sys.exit(0)
    backup=Path('/root/it-baby-profile-'+datetime.now().strftime('%Y%m%d-%H%M%S'))
    backup.mkdir(mode=0o700)
    (backup/'new-files.json').write_text(json.dumps(new_paths,indent=2))
    for name in files:
        target=root/name
        if target.exists():
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved);os.chmod(saved,0o600)
    for name in files:
        target=root/name;meta=target.stat() if target.exists() else (root/'app').stat()
        target.parent.mkdir(parents=True,exist_ok=True)
        fd,tmp=tempfile.mkstemp(prefix='.it-baby-',dir=target.parent)
        with os.fdopen(fd,'w') as stream:stream.write(files[name])
        os.chmod(tmp,0o644);os.chown(tmp,meta.st_uid,meta.st_gid);os.replace(tmp,target)
    print('APPLIED; private source backup:',backup)
    print('Next: migrate only the new file; run isolated tests and --dry-run before enabling cron.')
